namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

@page "/recipes/{Category?}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>Recipes - @CategoryDisplay</PageTitle>

<h1>@CategoryDisplay Recipes</h1>

@if (!string.IsNullOrEmpty(Category))
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/recipes">All Recipes</a></li>
            <li class="breadcrumb-item active">@CategoryDisplay</li>
        </ol>
    </nav>

    @if (Recipes.Count == 0)
    {
        <p>No recipes found in this category.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in Recipes)
            {
                <div class="col-md-6 mb-3">
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">
                                ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}
else
{
    <p>Select a category to browse recipes, or view all recipes below.</p>
    <div class="row">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            <span class="badge bg-secondary">@recipe.Category</span>
                            ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string? Category { get; set; }

    private List<RecipeShare.Models.Recipe> Recipes { get; set; } = new();

    private string CategoryDisplay => Category switch
    {
        "pasta" => "Pasta & Noodles",
        "salads" => "Salads & Soups",
        "desserts" => "Desserts",
        "meat" => "Meat & Poultry",
        "seafood" => "Seafood",
        "vegetarian" => "Vegetarian",
        _ => "All"
    };

    protected override void OnInitialized()
    {
        Recipes = string.IsNullOrEmpty(Category)
            ? RecipeService.GetAll()
            : RecipeService.GetByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (Recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="/recipes" class="btn btn-primary">Browse All Recipes</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/recipes/@Recipe.Category">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <h1>@Recipe.Title</h1>

    <div class="mb-4">
        <StarRating RecipeId="Recipe.Id" CurrentRating="Recipe.AverageRating" RatingCount="Recipe.RatingCount" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-3">
                <div class="card-header"><strong>Ingredients</strong></div>
                <div class="card-body">
                    <ul class="mb-0">
                        @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li>@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><strong>Instructions</strong></div>
                <div class="card-body">
                    @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeShare.Models.Recipe? Recipe { get; set; }

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="d-inline-block">
    <span class="me-2">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span role="button" style="cursor:pointer; font-size:1.5rem;"
                  @onclick="() => Rate(star)">
                @(star <= DisplayRating ? "★" : "☆")
            </span>
        }
    </span>
    <span class="text-muted">
        @if (UserRating > 0)
        {
            <text>You rated @UserRating/5 · </text>
        }
        @CurrentRating.ToString("F1") avg (@RatingCount ratings)
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int UserRating { get; set; }
    private int DisplayRating => UserRating > 0 ? UserRating : (int)Math.Round(CurrentRating);

    private void Rate(int stars)
    {
        UserRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <strong>Thank you!</strong> Your recipe "@Title" has been submitted successfully.
        <a href="/recipes">Browse all recipes</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-8">
            <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
                <DataAnnotationsValidator />

                <div class="mb-3">
                    <label for="title" class="form-label">Recipe Title</label>
                    <InputText id="title" class="form-control" @bind-Value="Title" placeholder="e.g., Grandma's Apple Pie" />
                    <ValidationMessage For="() => Title" />
                </div>

                <div class="mb-3">
                    <label for="category" class="form-label">Category</label>
                    <InputSelect id="category" class="form-select" @bind-Value="Category">
                        <option value="">-- Select a category --</option>
                        <option value="pasta">Pasta & Noodles</option>
                        <option value="salads">Salads & Soups</option>
                        <option value="desserts">Desserts</option>
                        <option value="meat">Meat & Poultry</option>
                        <option value="seafood">Seafood</option>
                        <option value="vegetarian">Vegetarian</option>
                    </InputSelect>
                    <ValidationMessage For="() => Category" />
                </div>

                <div class="mb-3">
                    <label for="ingredients" class="form-label">Ingredients</label>
                    <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="Ingredients"
                                   placeholder="One ingredient per line" />
                    <ValidationMessage For="() => Ingredients" />
                </div>

                <div class="mb-3">
                    <label for="steps" class="form-label">Steps</label>
                    <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Steps"
                                   placeholder="Describe each step on a new line" />
                    <ValidationMessage For="() => Steps" />
                </div>

                <button type="submit" class="btn btn-primary" disabled="@(!IsValid)">Submit Recipe</button>
            </EditForm>
        </div>
    </div>
}

@code {
    private string Title { get; set; } = string.Empty;
    private string Category { get; set; } = string.Empty;
    private string Ingredients { get; set; } = string.Empty;
    private string Steps { get; set; } = string.Empty;
    private bool Submitted { get; set; }

    private bool IsValid => !string.IsNullOrWhiteSpace(Title)
                         && !string.IsNullOrWhiteSpace(Category)
                         && !string.IsNullOrWhiteSpace(Ingredients)
                         && !string.IsNullOrWhiteSpace(Steps);

    private void HandleSubmit()
    {
        if (!IsValid) return;

        RecipeService.AddRecipe(new Recipe
        {
            Title = Title,
            Category = Category,
            Ingredients = Ingredients,
            Steps = Steps,
            AverageRating = 0,
            RatingCount = 0
        });

        Submitted = true;
    }
}

